// Builds the file tree's icon set: a small slice of Material Icon Theme (MIT)
// for the names and extensions people meet most, so the mod stays small.
//
//   node scripts/build-file-icons.mjs <file-icons mod folder>
//
// The source is a folder with `icons.js` (material-icon-theme's tables, as
// generated by github.com/LaiqianDS/herdr-mods) and `icons/*.svg`.
// Writes mods/2code/lib/fileIcons.js and mods/2code/icons/files/.
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const src = resolve(process.argv[2] ?? "");
if (!existsSync(join(src, "icons.js"))) throw new Error("usage: build-file-icons.mjs <folder with icons.js and icons/>");
// icons.js is `export default {...};` around plain JSON: read it as data,
// never run it.
const text = readFileSync(join(src, "icons.js"), "utf8");
const body = text.slice(text.indexOf("export default") + "export default".length).trim().replace(/;\s*$/, "");
const ICONS = JSON.parse(body);
const root = resolve(import.meta.dirname, "..");
const out = join(root, "mods/2code/icons/files");

const EXTENSIONS = `js mjs cjs jsx ts tsx mts cts d.ts json jsonc json5 md mdx markdown css scss sass less styl html htm vue svelte astro
  py pyi ipynb rb go rs java kt kts scala swift m mm c h cpp cc cxx hpp cs fs php pl lua r jl dart ex exs erl hrl hs ml clj zig nim
  sh bash zsh fish ps1 bat cmd yml yaml toml ini conf cfg env properties xml plist svg png jpg jpeg gif webp ico bmp tiff avif
  pdf zip gz tgz tar rar 7z lock sql db sqlite graphql gql proto prisma tf hcl nix txt log csv tsv wasm gradle csproj sln vim el
  mp3 wav mp4 mov webm ttf otf woff woff2 diff patch pem crt key`.split(/\s+/).filter(Boolean);
const FILE_NAMES = `package.json package-lock.json bun.lock bun.lockb yarn.lock pnpm-lock.yaml pnpm-workspace.yaml tsconfig.json jsconfig.json
  .gitignore .gitattributes .gitmodules .gitkeep .editorconfig .prettierrc .prettierignore .eslintrc .eslintrc.json eslint.config.js
  eslint.config.mjs .npmrc .nvmrc .node-version .env .env.local .env.example vite.config.ts vite.config.js vitest.config.ts
  next.config.js next.config.mjs next.config.ts tailwind.config.js tailwind.config.ts postcss.config.js biome.json deno.json
  dockerfile docker-compose.yml docker-compose.yaml compose.yaml .dockerignore makefile justfile cargo.toml cargo.lock
  go.mod go.sum gemfile gemfile.lock rakefile requirements.txt pyproject.toml setup.py readme.md license license.md licence
  changelog.md contributing.md agents.md claude.md netlify.toml vercel.json components.json .github favicon.ico robots.txt`.split(/\s+/).filter(Boolean);
const FOLDER_NAMES = `src source lib libs test tests __tests__ spec docs doc public static assets images img icons fonts scripts tools
  .github .vscode .idea node_modules dist build out target components hooks utils helpers config configs app pages routes api
  server client styles css website packages examples e2e .git migrations db database i18n locales messages bin vendor mods
  themes layouts types typings models services store stores views templates plugins middleware .cache logs tmp temp`.split(/\s+/).filter(Boolean);

const used = new Set([ICONS.file, ICONS.folder, `${ICONS.folder}-open`]);
const pick = (table, keys) => {
  const out = {}, light = {};
  for (const k of keys) {
    const id = ICONS[table][k], lid = ICONS.light?.[table]?.[k];
    if (id) { out[k] = id; used.add(id); if (table === "folderNames") used.add(`${id}-open`); }
    if (lid) { light[k] = lid; used.add(lid); if (table === "folderNames") used.add(lid.replace(/_light$/, "-open_light")); }
  }
  return [out, light];
};
const [fileExtensions, lightExt] = pick("fileExtensions", EXTENSIONS);
const [fileNames, lightNames] = pick("fileNames", FILE_NAMES);
const [folderNames, lightFolders] = pick("folderNames", FOLDER_NAMES);

rmSync(out, { recursive: true, force: true });
mkdirSync(out, { recursive: true });
let copied = 0;
for (const id of used) {
  const file = join(src, "icons", `${id}.svg`);
  if (existsSync(file)) { cpSync(file, join(out, `${id}.svg`)); copied++; }
}
const license = ["LICENSE-material-icon-theme.txt", "LICENSE"].map((f) => join(src, f)).find(existsSync);
if (license) cpSync(license, join(out, "LICENSE-material-icon-theme.txt"));

const table = { file: ICONS.file, folder: ICONS.folder, fileExtensions, fileNames, folderNames, light: { fileExtensions: lightExt, fileNames: lightNames, folderNames: lightFolders } };
writeFileSync(join(root, "mods/2code/lib/fileIcons.js"), `// Generated by scripts/build-file-icons.mjs from material-icon-theme (MIT,
// icons/files/LICENSE-material-icon-theme.txt). Do not edit; re-run the script.
// Lookup after material-icon-theme's rules as github.com/LaiqianDS/herdr-mods
// applies them: a name beats an extension, the longest extension wins, light
// themes try the light table first. Unknown names get the plain file / folder.
const ICONS = ${JSON.stringify(table)};
const DIR = "mods/2code/icons/files";
const have = new Set(${JSON.stringify([...used].filter((id) => existsSync(join(src, "icons", `${id}.svg`))))});
const find = (table, key, dark) => (dark ? undefined : ICONS.light[table][key]) ?? ICONS[table][key];
const svg = (id, fallback) => \`\${DIR}/\${have.has(id) ? id : fallback}.svg\`;

export function fileIcon(path, dir, open, dark) {
  const name = path.toLowerCase().split("/").pop();
  if (dir) {
    const id = find("folderNames", name, dark) ?? find("folderNames", name.replace(/^[._-]/, ""), dark) ?? ICONS.folder;
    const openId = id.endsWith("_light") ? \`\${id.slice(0, -6)}-open_light\` : \`\${id}-open\`;
    return open ? svg(openId, \`\${ICONS.folder}-open\`) : svg(id, ICONS.folder);
  }
  let id = find("fileNames", name, dark);
  for (let dot = name.indexOf("."); !id && dot !== -1; dot = name.indexOf(".", dot + 1)) id = find("fileExtensions", name.slice(dot + 1), dark);
  return svg(id ?? ICONS.file, ICONS.file);
}
`);
console.log(`${copied} icons, ${Object.keys(fileExtensions).length} extensions, ${Object.keys(fileNames).length} names, ${Object.keys(folderNames).length} folders`);
